		$P = &$this->P;
		$phi = &$this->phi;
		$h0 = $h[0] ?? 0.0;
		$h1 = $h[1] ?? 0.0;
		$h2 = $h[2] ?? 0.0;
		$h3 = $h[3] ?? 0.0;
		$f0 = $P[0] * $h0 + $P[1] * $h1 + $P[2] * $h2 + $P[3] * $h3;
		$phi[0] = $f0;
		$f1 = $P[4] * $h0 + $P[5] * $h1 + $P[6] * $h2 + $P[7] * $h3;
		$phi[1] = $f1;
		$f2 = $P[8] * $h0 + $P[9] * $h1 + $P[10] * $h2 + $P[11] * $h3;
		$phi[2] = $f2;
		$f3 = $P[12] * $h0 + $P[13] * $h1 + $P[14] * $h2 + $P[15] * $h3;
		$phi[3] = $f3;
