	public function commitScalar(float $r): void
	{
		$P = &$this->P;
		$phi = $this->phi;
		$inv = 1.0 / ($this->hPh + $r);
		$k0 = $phi[0] * $inv;
		$k1 = $phi[1] * $inv;
		$k2 = $phi[2] * $inv;
		$k3 = $phi[3] * $inv;
